// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.deal(caller, 0);
        vm.startPrank(caller);

        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }
        vm.stopPrank();

        if (success) {
            assertEq(c.owner(), caller);
        }
    }
}
